// 📁 src/app/core/models/property.interface.ts
// 🏠 INTERFACES SIMPLIFICADAS PARA UN SOLO LUGAR

export type PropertyType = 'habitacion' | 'suite' | 'apartamento' | 'studio';

// 🏠 Solo una zona: la casa principal
export type ZoneType = 'casa-norte-armenia';

export type AmenityType = 
  | 'wifi' 
  | 'parking'
  | 'breakfast' 
  | 'kitchen'
  | 'ac'
  | 'tv'
  | 'washing-machine'
  | 'security'
  | 'elevator'
  | 'balcony';

export type ServiceType = 
  | 'cleaning'
  | 'transport' 
  | 'luggage-storage'
  | 'concierge'
  | 'tour-info'
  | 'late-checkin';

export interface Property {
  id: string;
  title: string;
  location: string;
  zone: ZoneType; // Simplificado a una sola zona
  address?: string;
  description: string;
  
  // 💰 Precios
  pricePerNight: number;
  pricePerWeek?: number;
  pricePerMonth?: number;
  currency: 'COP';
  
  // ⭐ Calificaciones
  rating: number;
  reviewsCount: number;
  
  // 🖼️ Imágenes
  image: string;
  images?: string[];
  
  // 🏠 Características físicas
  propertyType: PropertyType;
  bedrooms: number;
  bathrooms: number;
  maxGuests: number;
  area?: number;
  floor?: number;
  
  // 🎯 Características específicas
  features: string[];
  amenities: AmenityType[];
  services: ServiceType[];
  
  // 👤 Información del anfitrión
  hostName: string;
  hostPhoto?: string;
  hostWhatsapp?: string;
  responseTime?: string;
  
  // 📍 Ubicación y acceso
  nearbyPlaces: string[];
  transportAccess: string[];
  
  // ⏰ Políticas
  checkInTime: string;
  checkOutTime: string;
  minimumStay?: number;
  cancellationPolicy?: 'flexible' | 'moderada' | 'estricta';
  
  // 🏷️ Estados
  isFavorite: boolean;
  isVerified: boolean;
  isInstantBook: boolean;
  isAvailable: boolean;
  
  // 📅 Fechas
  createdAt: string;
  updatedAt: string;
}

// 🛏️ INTERFAZ ESPECÍFICA PARA HABITACIÓN
export interface Room extends Property {
  roomNumber?: string;
  roomFeatures: string[];
  isOccupied?: boolean;
  lastCleaned?: string;
}

// 🎛️ CONFIGURACIÓN DE TARJETAS (SIMPLIFICADA)
export interface PropertyCardConfig {
  displayMode: 'compact' | 'detailed' | 'horizontal';
  showFavoriteButton: boolean;
  showPricing: boolean;
  showFeatures: boolean;
  showContact: boolean;
  showAvailability: boolean;
}

// 🔍 FILTROS SIMPLIFICADOS (SIN ZONAS)
export interface PropertyFilters {
  propertyTypes: PropertyType[];
  amenities: AmenityType[];
  services: ServiceType[];
  minPrice: number;
  maxPrice: number;
  minRating: number;
  maxGuests: number;
  instantBook: boolean;
  verified: boolean;
  available: boolean;
}

// 🏠 INFORMACIÓN DEL LUGAR PRINCIPAL
export const ARMENIA_NORTH_ACCOMMODATION = {
  'casa-norte-armenia': {
    name: 'Casa Norte Armenia',
    description: 'Hermosa casa en el corazón del norte de Armenia',
    icon: '🏠',
    location: 'Norte de Armenia, Quindío'
  }
};

// 🏷️ ETIQUETAS DE TIPOS DE HABITACIÓN
export const PROPERTY_TYPE_LABELS = {
  'habitacion': 'Habitación Privada',
  'suite': 'Suite',
  'apartamento': 'Apartamento Completo',
  'studio': 'Studio'
};

// 🎯 ETIQUETAS DE AMENIDADES
export const AMENITY_LABELS = {
  'wifi': 'WiFi gratis',
  'parking': 'Parqueadero',
  'breakfast': 'Desayuno incluido',
  'kitchen': 'Cocina equipada',
  'ac': 'Aire acondicionado',
  'tv': 'Televisión',
  'washing-machine': 'Lavadora',
  'security': 'Vigilancia 24h',
  'elevator': 'Ascensor',
  'balcony': 'Balcón'
};

// 🛎️ ETIQUETAS DE SERVICIOS
export const SERVICE_LABELS = {
  'cleaning': 'Servicio de limpieza',
  'transport': 'Transporte al aeropuerto',
  'luggage-storage': 'Guarda equipaje',
  'concierge': 'Servicio de conserjería',
  'tour-info': 'Información turística',
  'late-checkin': 'Check-in tardío'
};

// 💰 RANGOS DE PRECIO ESPECÍFICOS PARA LAS HABITACIONES
export const ROOM_PRICE_RANGES = [
  { min: 0, max: 50000, label: 'Hasta $50.000', category: 'económico' },
  { min: 50000, max: 70000, label: '$50.000 - $70.000', category: 'standard' },
  { min: 70000, max: 90000, label: '$70.000 - $90.000', category: 'superior' },
  { min: 90000, max: 999999, label: 'Más de $90.000', category: 'premium' }
];

// 👥 CAPACIDAD DE HUÉSPEDES
export const GUEST_CAPACITY_OPTIONS = [
  { value: 1, label: '1 huésped' },
  { value: 2, label: '2 huéspedes' },
  { value: 3, label: '3+ huéspedes' }
];

// ⭐ NIVELES DE CALIFICACIÓN
export const RATING_LEVELS = [
  { min: 0, label: 'Cualquier calificación' },
  { min: 4.0, label: '4.0+ Excelente' },
  { min: 4.5, label: '4.5+ Excepcional' },
  { min: 4.8, label: '4.8+ Súper anfitrión' }
];

// 🏠 CATEGORÍAS DE HABITACIONES
export const ROOM_CATEGORIES = {
  economica: {
    name: 'Económica',
    priceRange: { min: 0, max: 50000 },
    description: 'Habitaciones cómodas y funcionales',
    icon: '💰'
  },
  standard: {
    name: 'Standard',
    priceRange: { min: 50000, max: 70000 },
    description: 'Habitaciones con comodidades adicionales',
    icon: '🛏️'
  },
  superior: {
    name: 'Superior',
    priceRange: { min: 70000, max: 90000 },
    description: 'Habitaciones amplias con amenidades premium',
    icon: '⭐'
  },
  premium: {
    name: 'Premium',
    priceRange: { min: 90000, max: 999999 },
    description: 'Habitaciones de lujo con servicios exclusivos',
    icon: '👑'
  }
};

// 🔧 FUNCIONES UTILITARIAS
export const getRoomCategory = (price: number): keyof typeof ROOM_CATEGORIES => {
  if (price <= 50000) return 'economica';
  if (price <= 70000) return 'standard';
  if (price <= 90000) return 'superior';
  return 'premium';
};

export const formatPrice = (price: number): string => {
  return new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: 'COP',
    minimumFractionDigits: 0
  }).format(price);
};

export const calculateDiscountPercentage = (regularPrice: number, discountPrice: number): number => {
  return Math.round(((regularPrice - discountPrice) / regularPrice) * 100);
};
